CREATE TABLE app.report_templates (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE app.report_template_versions (id uuid PRIMARY KEY, template_id uuid NOT NULL REFERENCES app.report_templates, version integer NOT NULL CHECK(version>0), schema_version integer NOT NULL CHECK(schema_version>0), layout jsonb NOT NULL CHECK(jsonb_typeof(layout)='object'), styles text NOT NULL, published_at timestamptz, UNIQUE(template_id,version));
CREATE FUNCTION app.guard_template() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,app AS $$
BEGIN
 IF OLD.published_at IS NOT NULL THEN RAISE EXCEPTION 'Published template is immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_template BEFORE UPDATE OR DELETE ON app.report_template_versions FOR EACH ROW EXECUTE FUNCTION app.guard_template();
CREATE TABLE app.reports (id uuid PRIMARY KEY, study_id uuid NOT NULL, protocol_revision_id uuid NOT NULL, template_version_id uuid NOT NULL REFERENCES app.report_template_versions, html_asset_id uuid NOT NULL, pdf_asset_id uuid NOT NULL, client_version text NOT NULL, renderer_version text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), data_snapshot jsonb NOT NULL CHECK(jsonb_typeof(data_snapshot)='object'), template_snapshot jsonb NOT NULL CHECK(jsonb_typeof(template_snapshot)='object'), manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(protocol_revision_id,study_id) REFERENCES app.protocol_revisions(id,study_id), FOREIGN KEY(html_asset_id,study_id) REFERENCES app.assets(id,study_id), FOREIGN KEY(pdf_asset_id,study_id) REFERENCES app.assets(id,study_id));
CREATE TABLE app.integration_settings (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('orthanc','1c')), endpoint text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), settings jsonb NOT NULL CHECK(jsonb_typeof(settings)='object'), row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));
CREATE TABLE app.integration_secrets (integration_id uuid PRIMARY KEY REFERENCES app.integration_settings, algorithm text NOT NULL CHECK(algorithm='AES-256-GCM'), key_id text NOT NULL, nonce bytea NOT NULL CHECK(octet_length(nonce)=12), ciphertext bytea NOT NULL CHECK(octet_length(ciphertext)>=16), UNIQUE(key_id,nonce));
CREATE TABLE app.app_settings (id uuid PRIMARY KEY, scope text NOT NULL, owner_key text NOT NULL, name text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), value jsonb NOT NULL, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0), UNIQUE(scope,owner_key,name));
CREATE TABLE app.upload_sessions (id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES app.studies, credential_id uuid NOT NULL REFERENCES app.api_credentials, asset_id uuid, expected_bytes bigint NOT NULL CHECK(expected_bytes>=0), expected_sha256 text NOT NULL CHECK(expected_sha256 ~ '^[0-9a-f]{64}$'), state text NOT NULL CHECK(state IN ('pending','verified','committed','expired','failed')), expires_at timestamptz NOT NULL, idempotency_key text NOT NULL, UNIQUE(credential_id,idempotency_key), FOREIGN KEY(asset_id,study_id) REFERENCES app.assets(id,study_id));
CREATE TABLE app.dicom_instances (id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES app.studies, protocol_revision_id uuid NOT NULL, source_asset_id uuid NOT NULL, dicom_asset_id uuid NOT NULL, study_instance_uid text NOT NULL, series_instance_uid text NOT NULL CHECK(length(series_instance_uid) BETWEEN 1 AND 64 AND series_instance_uid ~ '^[0-9]+(\.[0-9]+)+$'), sop_instance_uid text NOT NULL UNIQUE CHECK(length(sop_instance_uid) BETWEEN 1 AND 64 AND sop_instance_uid ~ '^[0-9]+(\.[0-9]+)+$'), orthanc_id text, sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), state text NOT NULL CHECK(state IN ('pending','sent','verified','failed')), UNIQUE(id,study_id), FOREIGN KEY(protocol_revision_id,study_id) REFERENCES app.protocol_revisions(id,study_id), FOREIGN KEY(source_asset_id,study_id) REFERENCES app.assets(id,study_id), FOREIGN KEY(dicom_asset_id,study_id) REFERENCES app.assets(id,study_id));
ALTER TABLE app.studies ADD UNIQUE(id,study_instance_uid);
ALTER TABLE app.dicom_instances ADD FOREIGN KEY(study_id,study_instance_uid) REFERENCES app.studies(id,study_instance_uid);
CREATE TABLE app.study_publications (id uuid PRIMARY KEY, study_id uuid NOT NULL, protocol_revision_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), schema_version integer NOT NULL CHECK(schema_version>0), manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'), state text NOT NULL CHECK(state IN ('pending','delivering','complete','failed')), completed_at timestamptz, CHECK((state='complete')=(completed_at IS NOT NULL)), UNIQUE(study_id,version), UNIQUE(id,study_id), FOREIGN KEY(protocol_revision_id,study_id) REFERENCES app.protocol_revisions(id,study_id));
CREATE TABLE app.delivery_jobs (id uuid PRIMARY KEY, study_id uuid NOT NULL, publication_id uuid NOT NULL, dicom_instance_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('pending','running','retry','complete','failed')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), next_attempt_at timestamptz NOT NULL DEFAULT now(), safe_error_code text, FOREIGN KEY(publication_id,study_id) REFERENCES app.study_publications(id,study_id), FOREIGN KEY(dicom_instance_id,study_id) REFERENCES app.dicom_instances(id,study_id), UNIQUE(publication_id,dicom_instance_id));
CREATE INDEX delivery_jobs_pending_idx ON app.delivery_jobs(next_attempt_at) WHERE state IN ('pending','retry');
CREATE TABLE app.integration_requests (source text NOT NULL, idempotency_key text NOT NULL, request_sha256 text NOT NULL CHECK(request_sha256 ~ '^[0-9a-f]{64}$'), state text NOT NULL CHECK(state IN ('pending','complete','failed')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(source,idempotency_key));
GRANT SELECT,INSERT,UPDATE ON app.report_templates,app.report_template_versions,app.integration_settings,app.integration_secrets,app.app_settings,app.upload_sessions,app.dicom_instances,app.study_publications,app.delivery_jobs,app.integration_requests TO colposcopy_app;
-- Rendered artifacts and snapshots are append-only for runtime.
GRANT SELECT,INSERT ON app.reports TO colposcopy_app;
